pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address depositor, uint256 depositAmount, uint256 collectAmount) public {
        // Ensure we are in admissible domain: deposit amount positive, depositor not zero address
        vm.assume(depositor != address(0));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, type(uint128).max);

        // Initialize the contract
        c.Initialized();

        // Perform a deposit from the fuzzed depositor
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // Record the total supply and contract balance before collect
        uint256 totalSupplyBefore = c.balances(depositor);
        uint256 contractBalanceBefore = address(c).balance;

        // Perform collect from the same depositor if eligible
        try c.Collect(collectAmount) {
            // success path – nothing needed here
        } catch {
            // revert path – if it reverts, invariant should still hold
        }

        // After the operation, invariant: sum of all known balances + contract balance must equal initial sum
        // Because we only deposited once, total known deposited = depositAmount
        // The invariant: balances[depositor] + address(c).balance == contractBalanceBefore + totalSupplyBefore
        // This must hold regardless of whether Collect succeeded or reverted.
        uint256 finalBalance = c.balances(depositor);
        uint256 finalContractBalance = address(c).balance;
        assertTrue(finalBalance + finalContractBalance == contractBalanceBefore + totalSupplyBefore);
    }
}

