pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount) public {
        // Admissible domain: caller not zero address, deposit > 0, collect > 0, and deposit does not overflow
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(depositAmount <= type(uint256).max / 2);
        // Initialize and set MinSum to 0 so Collect is allowed for any amount
        c.Initialized();
        c.SetMinSum(0);
        // Fund caller
        vm.deal(caller, depositAmount + collectAmount);
        // Record initial balance
        uint256 initialBalance = c.balances(caller);
        // Deposit
        vm.prank(caller);
        c.Deposit{value: depositAmount}();
        // The buggy code subtracts, so balance after deposit may be less than initial;
        // we cannot use it directly. We compute expected balance after deposit.
        uint256 expectedAfterDeposit = initialBalance + depositAmount;
        // Collect
        vm.prank(caller);
        c.Collect(collectAmount);
        // Final balance
        uint256 finalBalance = c.balances(caller);
        // The invariant: finalBalance = initialBalance + depositAmount - collectAmount
        // This holds for correct Deposit (addition), fails for buggy (subtraction)
        assertTrue(finalBalance == expectedAfterDeposit - collectAmount);
    }
}

