pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));
        vm.assume(depositAmt > 0 && depositAmt < type(uint256).max / 2);
        vm.assume(collectAmt > 0 && collectAmt <= depositAmt);

        // Initialize contract and set MinSum to allow collection
        c.Initialized();
        c.SetMinSum(0);

        // Record total deposited so far (initially zero)
        uint256 totalDeposited = 0;

        // Deposit as fuzzed caller
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();
        totalDeposited += depositAmt;

        // Collect as the same caller
        vm.prank(caller);
        try c.Collect(collectAmt) {} catch {}

        // Compute sum of all balances we know about (only the caller)
        uint256 sumBalances = c.balances(caller);

        // Invariant: sum of balances must be totalDeposited - totalCollected (which is collectAmt here)
        assertTrue(sumBalances == totalDeposited - collectAmt);
    }
}

